package com.fooddelivery.user.service;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;import org.junit.jupiter.api.Test;import com.fooddelivery.user.repository.UserRepository;import com.fooddelivery.user.mapper.UserMapper;import com.fooddelivery.user.entity.User;import com.fooddelivery.user.dto.UserDto;import java.util.*;class UserServiceTest{@Test void createUser(){UserRepository r=mock(UserRepository.class);UserMapper m=mock(UserMapper.class);UserService s=new UserService(r,m);UserDto d=new UserDto();User u=new User();when(m.toEntity(d)).thenReturn(u);when(r.save(u)).thenReturn(u);when(m.toDto(u)).thenReturn(d);assertThat(s.create(d)).isSameAs(d);verify(r).save(u);}}
